#!/usr/bin/env bash
# Adds the platform runners that are not committed to the repository.
#
# Android is committed (it hosts the CloudStream bridge). The other runners are
# generated by `flutter create`, which only adds missing files and never
# overwrites what is already tracked, so running this locally or in CI is safe
# and idempotent.
set -euo pipefail

cd "$(dirname "$0")/.."

echo "==> Generating platform runners"
flutter create \
  --platforms=ios,macos,windows,linux,web \
  --project-name aerostream \
  --org dev.aerostream \
  --description "AeroStream - plugin-driven media client" \
  .

# Web is only a build target for the settings/docs shell: the JavaScript
# sandbox cannot run there. Keep it out of the analyzer's way.
rm -rf web/icons/Icon-192.png.tmp

echo "==> Platform runners ready"
